extracted.mesh_code:
border C1(t=0.0, 1.0){x=t*2.0; y=0.0; label=1;}
border C2(t=0.0, 1.0){x=2.0; y=t; label=2;}
border C3(t=0.0, 1.0){x=2.0-t*2.0; y=1.0; label=3;}
border C4(t=0.0, 1.0){x=0.0; y=1.0-t; label=4;}
real a = 0.6;
border C11(t=0.0, a){x=0.2+t; y=0.2; label=10;}
border C12(t=0.0, a){x=0.2+a; y=0.2+t; label=10;}
border C13(t=0.0, a){x=0.2+a-t; y=0.2+a; label=10;}
border C14(t=0.0, a){x=0.2; y=0.2+a-t; label=10;}
int n = 60;
mesh Th = buildmesh(C1(n) + C2(n) + C3(n) + C4(n) + C11(n) + C12(n) + C13(n) + C14(n));
int[int] re = [0, 3];
Th = change(Th, reft=re);

